import json
import re
import sys
from html.parser import HTMLParser
from urllib.parse import parse_qsl, urlencode, urljoin, urlsplit, urlunsplit

BASE = "http://192.168.2.3:80/"
ORIGIN = ("http", "192.168.2.3:80")
INITIAL_PATHS = [
    "/",
    "/flag.txt",
    "/robots.txt",
    "/sitemap.xml",
    "/.well-known/security.txt",
    "/security.txt",
]
ACCESS_WORDS = ("file", "download", "read", "view", "document", "browse", "source", "flag", "media")
INPUT_WORDS = ("file", "path", "filename", "page", "url", "resource", "doc", "download", "include", "view", "read", "template")

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.links = []
        self.forms = []
        self.form = None
        self.anchor_text = None

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag == "a":
            self.anchor_text = []
            self._anchor_href = attrs.get("href", "")
        elif tag == "form":
            self.form = {"action": attrs.get("action", ""), "method": attrs.get("method", "get").lower(), "fields": []}
        elif self.form is not None and tag in ("input", "button", "select", "textarea"):
            name = attrs.get("name")
            if name:
                self.form["fields"].append((name, attrs.get("value", ""), attrs.get("type", "").lower()))

    def handle_startendtag(self, tag, attrs):
        self.handle_starttag(tag, attrs)

    def handle_data(self, data):
        if self.anchor_text is not None:
            self.anchor_text.append(data)

    def handle_endtag(self, tag):
        if tag == "a" and self.anchor_text is not None:
            self.links.append((self._anchor_href, " ".join(self.anchor_text).strip()))
            self.anchor_text = None
        elif tag == "form" and self.form is not None:
            self.forms.append(self.form)
            self.form = None


def find_stdout(obj):
    if isinstance(obj, dict):
        if isinstance(obj.get("stdout"), str):
            return obj["stdout"]
        for value in obj.values():
            found = find_stdout(value)
            if found is not None:
                return found
    elif isinstance(obj, list):
        for value in obj:
            found = find_stdout(value)
            if found is not None:
                return found
    return None


def same_origin(url):
    p = urlsplit(url)
    return p.scheme == ORIGIN[0] and p.netloc.lower() == ORIGIN[1]


def relevant(text):
    value = (text or "").lower()
    return any(word in value for word in ACCESS_WORDS)


def is_input_name(name):
    value = (name or "").lower()
    return any(word in value for word in INPUT_WORDS)


def normalize(url):
    p = urlsplit(url)
    path = p.path or "/"
    return urlunsplit((p.scheme, p.netloc, path, p.query, ""))


def body_and_headers(raw):
    # Preserve the original stream in the tool envelope; this is only for link discovery.
    chunks = re.split(r"\r?\n\r?\n", raw)
    if len(chunks) < 2:
        return "", raw
    return "\n\n".join(chunks[:-1]), chunks[-1]


def discovered_requests(url, raw):
    header_text, body = body_and_headers(raw)
    out = []
    for match in re.finditer(r"(?im)^Location:\s*(\S+)\s*$", header_text):
        target = urljoin(url, match.group(1))
        if same_origin(target):
            out.append((normalize(target), "same-origin redirect disclosed by response"))

    parser = PageParser()
    try:
        parser.feed(body)
    except Exception:
        pass

    for href, text in parser.links:
        if not href:
            continue
        target = urljoin(url, href)
        if not same_origin(target):
            continue
        if relevant(href) or relevant(text):
            out.append((normalize(target), "relevant same-origin link disclosed by response"))
        parts = urlsplit(target)
        pairs = parse_qsl(parts.query, keep_blank_values=True)
        changed = False
        replaced = []
        for key, value in pairs:
            if is_input_name(key):
                replaced.append((key, "flag.txt"))
                changed = True
            else:
                replaced.append((key, value))
        if changed:
            mutated = urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(replaced), ""))
            out.append((normalize(mutated), "flag.txt supplied through a disclosed file-related query input"))

    for form in parser.forms:
        if form["method"] != "get":
            continue
        action = urljoin(url, form["action"] or url)
        if not same_origin(action):
            continue
        keys = [field for field in form["fields"] if is_input_name(field[0])]
        if not keys:
            continue
        pairs = [(name, value) for name, value, kind in form["fields"] if kind not in ("submit", "button", "file", "image")]
        changed = False
        for index, (name, value) in enumerate(pairs):
            if is_input_name(name):
                pairs[index] = (name, "flag.txt")
                changed = True
        if changed:
            parts = urlsplit(action)
            existing = parse_qsl(parts.query, keep_blank_values=True)
            target = urlunsplit((parts.scheme, parts.netloc, parts.path, urlencode(existing + pairs), ""))
            out.append((normalize(target), "flag.txt supplied through a disclosed read-only GET form input"))
    return body, out


def main():
    try:
        import framework_evidence
    except Exception as exc:
        print(json.dumps({"error": "Could not import supplied framework_evidence helper", "detail": str(exc)}))
        return 2

    queue = [(urljoin(BASE, path), "requested resource") for path in INITIAL_PATHS]
    queued = {normalize(url) for url, _ in queue}
    visited = set()
    while queue:
        url, reason = queue.pop(0)
        url = normalize(url)
        if url in visited or not same_origin(url):
            continue
        visited.add(url)
        argv = ["curl", "--include", "--silent", "--show-error", "--max-time", "15", url]
        try:
            envelope = framework_evidence.run_tool(argv)
        except Exception as exc:
            print(json.dumps({"request_url": url, "discovery_reason": reason, "tool_error": str(exc)}, ensure_ascii=False))
            continue
        print(json.dumps({"request_url": url, "discovery_reason": reason, "tool_envelope": envelope}, ensure_ascii=False))
        raw = find_stdout(envelope)
        if raw is None:
            continue
        _, followups = discovered_requests(url, raw)
        for target, why in followups:
            target = normalize(target)
            if target not in queued and target not in visited and same_origin(target):
                queued.add(target)
                queue.append((target, why))
    return 0

if __name__ == "__main__":
    sys.exit(main())

