import json
import socket
import struct
import sys

HOST = "192.168.2.255"
PORT = 3306
TIMEOUT = 8
MAX_PACKET = 16 * 1024 * 1024

CLIENT_LONG_PASSWORD = 0x00000001
CLIENT_LONG_FLAG = 0x00000004
CLIENT_PROTOCOL_41 = 0x00000200
CLIENT_TRANSACTIONS = 0x00002000
CLIENT_SECURE_CONNECTION = 0x00008000
CLIENT_MULTI_RESULTS = 0x00020000
CLIENT_PS_MULTI_RESULTS = 0x00040000
CLIENT_PLUGIN_AUTH = 0x00080000


def recv_exact(sock, count):
    chunks = []
    remaining = count
    while remaining:
        part = sock.recv(remaining)
        if not part:
            raise EOFError("connection closed while reading a MySQL packet")
        chunks.append(part)
        remaining -= len(part)
    return b"".join(chunks)


def read_packet(sock):
    header = recv_exact(sock, 4)
    size = header[0] | (header[1] << 8) | (header[2] << 16)
    sequence = header[3]
    if size > MAX_PACKET:
        raise ValueError("server packet exceeds the 16 MiB observation limit")
    return sequence, recv_exact(sock, size)


def send_packet(sock, payload, sequence):
    if len(payload) > 0xFFFFFF:
        raise ValueError("outgoing packet is too large")
    header = bytes((len(payload) & 255, (len(payload) >> 8) & 255,
                    (len(payload) >> 16) & 255, sequence & 255))
    sock.sendall(header + payload)


def nul_string(data, offset):
    end = data.find(b"\x00", offset)
    if end < 0:
        return data[offset:], len(data)
    return data[offset:end], end + 1


def lenenc(data, offset):
    if offset >= len(data):
        raise ValueError("truncated length-encoded integer")
    first = data[offset]
    offset += 1
    if first < 0xFB:
        return first, offset
    if first == 0xFB:
        return None, offset
    if first == 0xFC:
        width = 2
    elif first == 0xFD:
        width = 3
    elif first == 0xFE:
        width = 8
    else:
        raise ValueError("invalid length-encoded integer")
    if offset + width > len(data):
        raise ValueError("truncated length-encoded integer value")
    return int.from_bytes(data[offset:offset + width], "little"), offset + width


def lenenc_bytes(data, offset):
    size, offset = lenenc(data, offset)
    if size is None:
        return None, offset
    end = offset + size
    if end > len(data):
        raise ValueError("truncated length-encoded string")
    return data[offset:end], end


def text(value):
    if value is None:
        return None
    return value.decode("utf-8", "replace")


def parse_error(payload):
    result = {"type": "error", "code": None, "sql_state": None, "message": ""}
    if len(payload) >= 3:
        result["code"] = int.from_bytes(payload[1:3], "little")
    offset = 3
    if len(payload) >= 9 and payload[3:4] == b"#":
        result["sql_state"] = payload[4:9].decode("ascii", "replace")
        offset = 9
    result["message"] = payload[offset:].decode("utf-8", "replace")
    return result


def parse_handshake(payload):
    if not payload:
        raise ValueError("empty handshake packet")
    if payload[0] != 10:
        return {"protocol_version": payload[0], "supported_protocol": False}, 0, ""
    server_version, pos = nul_string(payload, 1)
    if pos + 4 + 8 + 1 + 2 > len(payload):
        raise ValueError("truncated protocol-10 handshake")
    connection_id = int.from_bytes(payload[pos:pos + 4], "little")
    pos += 4
    seed1 = payload[pos:pos + 8]
    pos += 9  # includes filler byte
    cap_low = int.from_bytes(payload[pos:pos + 2], "little")
    pos += 2
    if pos >= len(payload):
        caps = cap_low
        plugin = ""
        seed = seed1
    else:
        pos += 1  # character set
        pos += 2  # status flags
        if pos + 2 > len(payload):
            raise ValueError("truncated handshake capabilities")
        cap_high = int.from_bytes(payload[pos:pos + 2], "little")
        caps = cap_low | (cap_high << 16)
        pos += 2
        auth_len = payload[pos] if pos < len(payload) else 0
        pos += 1
        pos = min(pos + 10, len(payload))
        seed2_len = max(0, min(13, auth_len - 8)) if auth_len else 12
        seed2 = payload[pos:pos + seed2_len]
        pos += len(seed2)
        seed = seed1 + seed2.rstrip(b"\x00")
        plugin = ""
        if caps & CLIENT_PLUGIN_AUTH and pos < len(payload):
            plugin_bytes, _ = nul_string(payload, pos)
            plugin = plugin_bytes.decode("ascii", "replace")
    return {
        "protocol_version": 10,
        "server_version": server_version.decode("ascii", "replace"),
        "connection_id": connection_id,
        "auth_plugin": plugin or None,
        "capabilities": "0x%08x" % caps,
    }, caps, plugin


def make_auth_response(server_caps, plugin):
    requested = (CLIENT_LONG_PASSWORD | CLIENT_LONG_FLAG | CLIENT_PROTOCOL_41 |
                 CLIENT_TRANSACTIONS | CLIENT_SECURE_CONNECTION |
                 CLIENT_MULTI_RESULTS | CLIENT_PS_MULTI_RESULTS | CLIENT_PLUGIN_AUTH)
    caps = requested & server_caps
    if not (server_caps & CLIENT_PROTOCOL_41):
        raise ValueError("server does not advertise CLIENT_PROTOCOL_41; safe login not implemented")
    # The only identity and authentication material sent is the empty anonymous identity
    # and an empty authentication response.
    packet = struct.pack("<IIB", caps, 1024 * 1024, 45) + (b"\x00" * 23)
    packet += b"\x00"  # empty username
    if caps & CLIENT_SECURE_CONNECTION:
        packet += b"\x00"  # zero-length authentication response
    else:
        packet += b"\x00"  # legacy empty NUL-terminated response
    if caps & CLIENT_PLUGIN_AUTH:
        packet += (plugin or "mysql_native_password").encode("ascii", "replace") + b"\x00"
    return packet


def read_auth_result(sock, sequence):
    exchanges = []
    for _ in range(6):
        seq, payload = read_packet(sock)
        if not payload:
            return {"outcome": "inconclusive", "error": "empty authentication response", "exchanges": exchanges}, seq
        marker = payload[0]
        if marker == 0x00:
            return {"outcome": "granted", "server_ok_packet": payload.hex(), "exchanges": exchanges}, seq
        if marker == 0xFF:
            return {"outcome": "denied", "server_error": parse_error(payload), "exchanges": exchanges}, seq
        if marker == 0xFE and len(payload) > 1:
            switched_plugin, _ = nul_string(payload, 1)
            plugin_name = switched_plugin.decode("ascii", "replace")
            exchanges.append({"auth_switch_plugin": plugin_name})
            send_packet(sock, b"", (seq + 1) & 255)
            continue
        if marker == 0x01 and len(payload) > 1:
            # caching_sha2_password status 0x03 means authentication succeeded; 0x04
            # requests full authentication. Respond only with an empty password, never
            # attempt a credential guess or initiate an alternate authentication path.
            status = payload[1]
            exchanges.append({"auth_more_data_status": status})
            if status == 0x03:
                continue
            if status == 0x04:
                send_packet(sock, b"\x00", (seq + 1) & 255)
                continue
            return {"outcome": "inconclusive", "error": "unsupported authentication continuation", "exchanges": exchanges}, seq
        return {"outcome": "inconclusive", "unexpected_server_packet": payload.hex(), "exchanges": exchanges}, seq
    return {"outcome": "inconclusive", "error": "too many authentication exchanges", "exchanges": exchanges}, sequence


def column_name(payload):
    # Protocol-4.1 column definition: six length-encoded strings, then fixed fields.
    try:
        offset = 0
        fields = []
        for _ in range(6):
            value, offset = lenenc_bytes(payload, offset)
            fields.append(value)
        return text(fields[4]) if len(fields) > 4 else None
    except Exception:
        return None


def decode_row(payload, count):
    offset = 0
    values = []
    for _ in range(count):
        value, offset = lenenc_bytes(payload, offset)
        values.append(None if value is None else value.decode("utf-8", "replace"))
    return values


def query(sock, sql):
    send_packet(sock, b"\x03" + sql.encode("utf-8"), 0)
    seq, first = read_packet(sock)
    if not first:
        return {"sql": sql, "status": "inconclusive", "error": "empty response"}
    if first[0] == 0xFF:
        return {"sql": sql, "status": "error", "server_error": parse_error(first)}
    if first[0] == 0x00:
        return {"sql": sql, "status": "ok", "ok_packet": first.hex()}
    if first[0] == 0xFB:
        return {"sql": sql, "status": "refused", "error": "server requested LOCAL INFILE; client did not send a file"}
    try:
        column_count, _ = lenenc(first, 0)
        if column_count is None or column_count > 4096:
            raise ValueError("invalid or excessive result column count")
        names = []
        for _ in range(column_count):
            _, definition = read_packet(sock)
            if definition and definition[0] == 0xFF:
                return {"sql": sql, "status": "error", "server_error": parse_error(definition)}
            names.append(column_name(definition))
        # Consume the optional metadata terminator (EOF on older servers).
        _, packet = read_packet(sock)
        rows = []
        if packet and packet[0] == 0xFF:
            return {"sql": sql, "status": "error", "server_error": parse_error(packet)}
        if not (packet[0] == 0xFE and len(packet) < 9):
            while True:
                if packet and packet[0] == 0xFF:
                    return {"sql": sql, "status": "error", "server_error": parse_error(packet)}
                if packet and packet[0] == 0xFE and len(packet) < 9:
                    break
                if packet and packet[0] == 0x00 and len(packet) >= 7:
                    # With CLIENT_DEPRECATE_EOF, an OK packet terminates rows.
                    # This client does not request that capability; ordinary rows are decoded.
                    pass
                rows.append(decode_row(packet, column_count))
                _, packet = read_packet(sock)
                if len(rows) >= 1000:
                    return {"sql": sql, "status": "partial", "columns": names, "rows": rows,
                            "coverage_note": "stopped after 1000 rows"}
        return {"sql": sql, "status": "result", "columns": names, "rows": rows}
    except Exception as exc:
        return {"sql": sql, "status": "parse_or_protocol_error", "error": str(exc)}


def main():
    evidence = {"target": "%s:%d" % (HOST, PORT), "transport": "TCP/MySQL protocol",
                "authentication_attempt": {"username": "", "authentication_response": "empty",
                                            "credential_guessing": False}}
    try:
        with socket.create_connection((HOST, PORT), timeout=TIMEOUT) as sock:
            sock.settimeout(TIMEOUT)
            seq, greeting = read_packet(sock)
            handshake, server_caps, plugin = parse_handshake(greeting)
            evidence["handshake"] = handshake
            if not handshake.get("supported_protocol") is False:
                send_packet(sock, make_auth_response(server_caps, plugin), (seq + 1) & 255)
